namespace sv_24cc096aecf0482c84c1565d2a4958d5.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Fires OnAlertCountChanged when new data arrives so all subscribed
/// components update — not just the one that triggered the poll.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscribers;

    public int CurrentAlertCount { get; private set; }
    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query for items below minimum stock levels.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call returning 0–15.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begin polling every 10 seconds. Multiple callers share the same timer;
    /// polling stops only when all callers have called StopPolling.
    /// </summary>
    public void StartPolling(string warehouseId, Func<string> getCurrentWarehouseId)
    {
        _subscribers++;
        if (_timer is not null) return; // already running

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(getCurrentWarehouseId, _cts.Token);
    }

    public void StopPolling()
    {
        _subscribers = Math.Max(0, _subscribers - 1);
        if (_subscribers > 0) return;

        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    /// <summary>Fetch fresh data and notify all subscribers.</summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(Func<string> getCurrentWarehouseId, CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync(getCurrentWarehouseId());

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAsync(getCurrentWarehouseId());
            }
        }
        catch (OperationCanceledException) { /* expected on dispose */ }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

