@inject sv_24cc096aecf0482c84c1565d2a4958d5.Services.WarehouseState Warehouse
@implements IDisposable
@rendermode InteractiveServer

<div class="d-flex align-items-center gap-2">
    <label class="fw-semibold text-nowrap mb-0" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="max-width: 280px;"
            value="@Warehouse.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in sv_24cc096aecf0482c84c1565d2a4958d5.Services.WarehouseState.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            Warehouse.SetWarehouse(id);
        }
    }

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _handler;
    }

    public void Dispose() => Warehouse.OnChange -= _handler;
}

