@page "/dashboard"
@inject sv_24cc096aecf0482c84c1565d2a4958d5.Services.WarehouseState Warehouse
@inject sv_24cc096aecf0482c84c1565d2a4958d5.Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @Warehouse.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-5">
            <strong>@Warehouse.CurrentWarehouseName</strong>
            <span class="text-muted">(@Warehouse.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="row g-3">
    <div class="col-md-4">
        <div class="card text-bg-@(AlertService.CurrentAlertCount > 10 ? "danger" : AlertService.CurrentAlertCount > 5 ? "warning" : "success")">
            <div class="card-body text-center">
                <h2 class="display-4">@AlertService.CurrentAlertCount</h2>
                <p class="card-text">Low-Stock Alerts</p>
                <small class="opacity-75">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Alert Details</div>
            <div class="card-body">
                @if (AlertService.CurrentAlertCount == 0)
                {
                    <p class="text-success mb-0">✅ All items are above minimum stock levels.</p>
                }
                else
                {
                    <p class="text-danger mb-0">
                        ⚠️ <strong>@AlertService.CurrentAlertCount item(s)</strong> at
                        <strong>@Warehouse.CurrentWarehouseName</strong> are below minimum stock levels.
                        Review and reorder as needed.
                    </p>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to alert updates so this page re-renders when polling finds new data
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Subscribe to warehouse changes so polling targets the new warehouse
        _warehouseHandler = async () =>
        {
            // Warehouse changed — fetch fresh data for the new site immediately
            await AlertService.RefreshAsync(Warehouse.CurrentWarehouseId);
            await InvokeAsync(StateHasChanged);
        };
        Warehouse.OnChange += _warehouseHandler;

        // Start polling while this page is visible
        AlertService.StartPolling(Warehouse.CurrentWarehouseId, () => Warehouse.CurrentWarehouseId);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.StopPolling();
    }
}

